namespace sv_3b427db2489b4cacbe85c0bdb9fb0432.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Raises <see cref="OnChange"/> so any subscribing component can re-render.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-1";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "WH-1", Name = "Warehouse A — Main Distribution" },
        new() { Id = "WH-2", Name = "Warehouse B — East Regional" },
        new() { Id = "WH-3", Name = "Warehouse C — West Regional" },
    ];

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_3b427db2489b4cacbe85c0bdb9fb0432.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribing components when fresh data arrives.
/// </summary>
public class InventoryAlertService
{
    private static readonly Random s_random = new();

    private int _latestCount;

    public int LatestCount => _latestCount;

    /// <summary>Fired after new alert data is fetched so every subscriber can re-render.</summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock level.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate I/O latency and a random result
        int count;
        lock (s_random) { count = s_random.Next(0, 16); }
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh data for the given warehouse and notifies all subscribers.
    /// Designed to be called from a single polling component.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        var count = await GetLowStockCountAsync(warehouseId);
        _latestCount = count;
        OnAlertDataChanged?.Invoke();
    }
}

@using sv_3b427db2489b4cacbe85c0bdb9fb0432.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 text-muted small" for="warehouseDropdown">Current Site</label>
    <select id="warehouseDropdown"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_3b427db2489b4cacbe85c0bdb9fb0432.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.LatestCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto" title="@AlertService.LatestCount low-stock items">
        @AlertService.LatestCount
    </span>
}

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += OnDataChanged;
    }

    private void OnDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnDataChanged;
    }
}

