@page "/dashboard"
@using sv_3b427db2489b4cacbe85c0bdb9fb0432.Services
@using sv_3b427db2489b4cacbe85c0bdb9fb0432.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            📍 @WarehouseState.CurrentWarehouseName
        </h5>
        <p class="text-muted mb-0">Selected warehouse for all operations on this page.</p>
    </div>
</div>

<div class="row g-4">
    <div class="col-md-4">
        <div class="card text-bg-@(AlertService.LatestCount > 5 ? "danger" : AlertService.LatestCount > 0 ? "warning" : "success")">
            <div class="card-body text-center">
                <h2 class="display-4">@AlertService.LatestCount</h2>
                <p class="mb-0">Low-Stock Alerts</p>
                <AlertBadge />
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Polling Status</div>
            <div class="card-body">
                @if (_isPolling)
                {
                    <p class="mb-0">
                        <span class="spinner-grow spinner-grow-sm text-primary me-2" role="status"></span>
                        Live polling every 10 seconds for <strong>@WarehouseState.CurrentWarehouseName</strong>
                    </p>
                }
                else
                {
                    <p class="text-muted mb-0">Polling stopped.</p>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private void OnWarehouseChanged()
    {
        // Warehouse changed — restart polling for the new warehouse
        InvokeAsync(async () =>
        {
            StopPolling();
            StateHasChanged();
            await StartPollingAsync();
        });
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _isPolling = true;
        StateHasChanged();

        var token = _cts.Token;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);

        try
        {
            while (!token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), token);
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped
        }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _isPolling = false;
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
    }
}

